import test from 'node:test';
import assert from 'node:assert/strict';
import { exportCsv } from '../src/export.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';

test('exportCsv returns string with header', () => {
  const result = exportCsv([]);
  assert.ok(typeof result === 'string');
  assert.ok(result.startsWith('number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n'));
});

test('exportCsv empty array returns only header', () => {
  const result = exportCsv([]);
  assert.equal(result, 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n');
});

test('exportCsv single invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 100 }],
  });
  assert.equal(r.ok, true);
  const r2 = issueInvoice(r.value, []);
  assert.equal(r2.ok, true);
  const result = exportCsv([r2.value]);
  assert.ok(result.includes('INV-2026-0001'));
  assert.ok(result.includes('Acme Corp'));
  assert.ok(result.includes('2026-10-07'));
  assert.ok(result.includes('2026-11-06'));
  assert.ok(result.includes('issued'));
});

test('exportCsv formats amounts with 2 decimals', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 100 }],
  });
  assert.equal(r.ok, true);
  const r2 = issueInvoice(r.value, []);
  assert.equal(r2.ok, true);
  const result = exportCsv([r2.value]);
  assert.ok(result.includes('850000.00'));
});

test('exportCsv ends lines with newline', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 100 }],
  });
  assert.equal(r.ok, true);
  const r2 = issueInvoice(r.value, []);
  assert.equal(r2.ok, true);
  const result = exportCsv([r2.value]);
  assert.ok(result.endsWith('\n'));
});

test('exportCsv multiple invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 100 }],
  });
  const r2 = issueInvoice(r1.value, []);
  const r3 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DEV-HOUR', qty: 50 }],
  });
  const r4 = issueInvoice(r3.value, ['INV-2026-0001']);
  const result = exportCsv([r2.value, r4.value]);
  const lines = result.split('\n');
  assert.equal(lines.length, 4);
  assert.ok(lines[1].includes('INV-2026-0001'));
  assert.ok(lines[2].includes('INV-2026-0002'));
});

test('exportCsv customer name appears in output', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 100 }],
  });
  const r2 = issueInvoice(r.value, []);
  const result = exportCsv([r2.value]);
  assert.ok(result.includes('Acme Corp'));
});

test('exportCsv handles customer with comma in name', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 100 }],
  });
  const r2 = issueInvoice(r.value, []);
  const result = exportCsv([r2.value]);
  assert.ok(result.includes('"Widgets Inc, LLC"'));
});

test('exportCsv escapes quotes in customer name', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 100 }],
  });
  const r2 = issueInvoice(r.value, []);
  const result = exportCsv([r2.value]);
  const lines = result.split('\n');
  const dataLine = lines[1];
  assert.ok(dataLine.includes('"Tech "'));
});

test('exportCsv all fields present', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 100 }],
  });
  const r2 = issueInvoice(r.value, []);
  const result = exportCsv([r2.value]);
  const lines = result.split('\n');
  const dataLine = lines[1];
  const fields = dataLine.split(',');
  assert.equal(fields.length, 10);
});

test('exportCsv with discounted invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(r.ok, true);
  const r2 = issueInvoice(r.value, []);
  const result = exportCsv([r2.value]);
  const lines = result.split('\n');
  const dataLine = lines[1];
  assert.ok(dataLine.includes('85000.00'));
  assert.ok(dataLine.includes('4250.00'));
});

test('exportCsv different statuses', () => {
  const draft = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 100, unitPrice: 8500, vatRate: 21, discountPercent: 5 }],
    terms: 'NET30',
    dueDate: '2026-11-06',
    number: 'INV-DRAFT',
  };
  const result = exportCsv([draft]);
  assert.ok(result.includes('draft'));
});

test('exportCsv order preserved', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 100 }],
  });
  const r2 = issueInvoice(r1.value, []);
  const r3 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-02',
    lines: [{ sku: 'DEV-HOUR', qty: 50 }],
  });
  const r4 = issueInvoice(r3.value, ['INV-2026-0001']);
  const r5 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-03',
    lines: [{ sku: 'DES-HOUR', qty: 75 }],
  });
  const r6 = issueInvoice(r5.value, ['INV-2026-0001', 'INV-2026-0002']);
  const result = exportCsv([r2.value, r4.value, r6.value]);
  const lines = result.split('\n');
  const inv1Line = lines.find(l => l.includes('INV-2026-0001'));
  const inv2Line = lines.find(l => l.includes('INV-2026-0002'));
  const inv3Line = lines.find(l => l.includes('INV-2026-0003'));
  assert.ok(inv1Line.indexOf('INV-2026-0001') < inv2Line.indexOf('INV-2026-0002'));
  assert.ok(inv2Line.indexOf('INV-2026-0002') < inv3Line.indexOf('INV-2026-0003'));
});

test('exportCsv with payments reduces due', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 100 }],
  });
  const r2 = issueInvoice(r.value, []);
  const invoiceWithPayment = {
    ...r2.value,
    status: 'partially_paid',
    payments: [{ amount: 50000, date: '2026-10-10' }],
  };
  const result = exportCsv([invoiceWithPayment]);
  const lines = result.split('\n');
  const dataLine = lines[1];
  const fields = dataLine.split(',');
  const due = parseFloat(fields[9]);
  assert.ok(due < 900000);
});

test('exportCsv VAT-exempt invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 2 }],
  });
  assert.equal(r.ok, true);
  const r2 = issueInvoice(r.value, []);
  const result = exportCsv([r2.value]);
  assert.ok(result.includes('0.00'));
  const lines = result.split('\n');
  const dataLine = lines[1];
  const fields = dataLine.split(',');
  assert.equal(fields[7], '0.00');
});

test('exportCsv with voucher', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 100 }],
  });
  assert.equal(r.ok, true);
  const invoiceWithVoucher = {
    ...r.value,
    voucher: { code: 'SUMMER20', amount: 50000 },
  };
  const r2 = issueInvoice(invoiceWithVoucher, []);
  const result = exportCsv([r2.value]);
  const lines = result.split('\n');
  const dataLine = lines[1];
  const fields = dataLine.split(',');
  const total = parseFloat(fields[8]);
  assert.ok(total < 900000);
});

test('exportCsv no comma in simple names', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 100 }],
  });
  const r2 = issueInvoice(r.value, []);
  const result = exportCsv([r2.value]);
  const lines = result.split('\n');
  const dataLine = lines[1];
  assert.ok(dataLine.includes('Acme Corp'));
  assert.ok(!dataLine.startsWith('"Acme Corp'));
});

test('exportCsv header is first line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 100 }],
  });
  const r2 = issueInvoice(r.value, []);
  const result = exportCsv([r2.value]);
  const firstLine = result.split('\n')[0];
  assert.equal(firstLine, 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
});

test('exportCsv amounts with cents', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    number: 'INV-001',
    lines: [{ qty: 1, unitPrice: 123, vatRate: 21, discountPercent: 0 }],
    terms: 'NET30',
    dueDate: '2026-11-06',
  };
  const result = exportCsv([invoice]);
  assert.ok(result.includes('1.23'));
});

test('exportCsv fields in correct order', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 100 }],
  });
  const r2 = issueInvoice(r.value, []);
  const result = exportCsv([r2.value]);
  const lines = result.split('\n');
  const dataLine = lines[1];
  const fields = dataLine.split(',');
  assert.equal(fields[0], 'INV-2026-0001');
  assert.ok(fields[1].includes('Corp'));
  assert.equal(fields[2], '2026-10-07');
  assert.equal(fields[3], '2026-11-06');
  assert.equal(fields[4], 'issued');
});

